import pathlib,shutil,json,hashlib
R=pathlib.Path(__file__).resolve().parent
(R/'pre-refinement').mkdir()
for n in ('monitor.ps1','event_queue.cs','LoopTiming.cs','collect.py','launch.ps1','analyze.py'):shutil.copyfile(R/n,R/'pre-refinement'/n)
p=R/'event_queue.cs';s=p.read_text()
s=s.replace('int CountOwned() {int n=0;for(int i=0;i<queue.Count;i++)if(sources.Contains(queue[i].SourceIdentifier))n++;return n;}', 'int CountOwned() {using(LoopTiming.Span("queue.CountOwned")){int n=0;for(int i=0;i<queue.Count;i++)if(sources.Contains(queue[i].SourceIdentifier))n++;return n;}}')
s=s.replace('int Index(QueueEntry e) {for(int i=0;i<queue.Count;i++)if(Object.ReferenceEquals(queue[i],e.Event))return i;return -1;}', 'int Index(QueueEntry e) {using(LoopTiming.Span("queue.reference.Index")){for(int i=0;i<queue.Count;i++)if(Object.ReferenceEquals(queue[i],e.Event))return i;return -1;}}')
s=s.replace('var ev=queue[i];if(!sources.Contains(ev.SourceIdentifier))continue;', 'PSEventArgs ev;using(LoopTiming.Span("queue.item.read")){ev=queue[i];}if(!sources.Contains(ev.SourceIdentifier))continue;')
s=s.replace('if(!entries.TryGetValue(ev,out var e)){Fail("Enqueue identity unavailable");Healthy();}', 'QueueEntry e;using(LoopTiming.Span("queue.identity.lookup")){if(!entries.TryGetValue(ev,out e)){Fail("Enqueue identity unavailable");Healthy();}}')
p.write_text(s)
p=R/'monitor.ps1';s=p.read_text()
s=s.replace("function Stamp($stage,$ev,$n) {", "function Stamp($stage,$ev,$n) {\n [LoopTiming]::Note('stamp.'+$stage+'.begin')")
s=s.replace("utc=[DateTime]::UtcNow.ToString('o')})\n}", "utc=[DateTime]::UtcNow.ToString('o')})\n [LoopTiming]::Note('stamp.'+$stage+'.end')\n}",1)
s=s.replace("$ev=$entry.Event;$id=$ev.SourceIdentifier", "Mark 'entry.properties.begin';$ev=$entry.Event;$id=$ev.SourceIdentifier;Mark 'entry.properties.end'")
s=s.replace("Mark 'event.begin';$n=$ev.SourceEventArgs.NewEvent;", "Mark 'event.begin';Mark 'event.payload.begin';$n=$ev.SourceEventArgs.NewEvent;Mark 'event.payload.end';")
s=s.replace("if([string]$n.ProcessName -match", "Mark 'event.metadata.begin'\n   if([string]$n.ProcessName -match")
s=s.replace("queuedUtc=$ev.TimeGenerated.ToUniversalTime().ToString('o')}\n", "queuedUtc=$ev.TimeGenerated.ToUniversalTime().ToString('o')}\n   Mark 'event.metadata.end'\n")
s=s.replace("Mark 'event.path.begin';$eventPath=Join-Path $root 'events.jsonl';Mark 'event.path.end'", "Mark 'event.path.begin';$eventPath=Join-Path $root 'events.jsonl';if($config.eventVolume -eq 'D'){$eventPath=Join-Path ('D:\\JARVIS-STAGE6-EVENTDRAIN-20260920\\'+$Run) 'events.jsonl'};Mark 'event.path.end'")
s=s.replace("'D:\\JARVIS-STAGE6-HEARTBEAT-STALL-20260920\\'", "'D:\\JARVIS-STAGE6-EVENTDRAIN-20260920\\'")
s=s.replace("$secondary.Add($watcher)","$secondary.Add($watcher)")
# 'none' telemetry removes the diagnostic secondary WMI observer, never the authoritative subscriptions/taps.
s=s.replace("foreach($pair in @(@('Win32_ProcessStartTrace','start'),@('Win32_ProcessStopTrace','stop'))){", "if($config.telemetry -ne 'none'){foreach($pair in @(@('Win32_ProcessStartTrace','start'),@('Win32_ProcessStopTrace','stop'))){")
s=s.replace("$secondary.Add($watcher)\n }", "$secondary.Add($watcher)\n }}")
p.write_text(s)
p=R/'LoopTiming.cs';p.write_text(p.read_text().replace('>400000','>1000000'))
p=R/'collect.py';s=p.read_text().replace("('smoke','a1','a2','a3','b','c','d','e','f','minimal')","('smoke','a1','a2','a3','minimal','persist-d','none','dhash')")
s=s.replace("if journal!=out/'heartbeat.jsonl':", "if config.get('eventVolume')=='D':\n  source=pathlib.Path('D:/JARVIS-STAGE6-EVENTDRAIN-20260920')/run/'events.jsonl';data=source.read_bytes();(out/'events.jsonl').write_bytes(data)\n  save('event-copy-verification.json',dict(source=str(source),sha256=hashlib.sha256(data).hexdigest(),copied_sha256=hashlib.sha256((out/'events.jsonl').read_bytes()).hexdigest()))\n if journal!=out/'heartbeat.jsonl':")
p.write_text(s)
p=R/'launch.ps1';s=p.read_text().replace("'smoke','a1','a2','a3','b','c','d','e','f','minimal'", "'a1','a2','a3','minimal','persist-d','none','dhash'")
start=s.index("$mode='sustained'");end=s.index('New-Item -ItemType Directory -Path $root',start)
s=s[:start]+"$mode='sustained';$volume='C';$eventVolume='C';$telemetry='full';$duration=150\nif($Run -eq 'dhash'){$mode='Dhash'}\nif($Run -eq 'minimal'){$telemetry='minimal'}\nif($Run -eq 'none'){$telemetry='none'}\nif($Run -eq 'persist-d'){$eventVolume='D'}\n"+s[end:]
s=s.replace("if($volume -eq 'D')", "if($eventVolume -eq 'D')").replace('D:\\JARVIS-STAGE6-HEARTBEAT-STALL-20260920','D:\\JARVIS-STAGE6-EVENTDRAIN-20260920')
s=s.replace("eventEvidenceVolume='C'", "eventVolume=$eventVolume")
s=s.replace("$p=Start-Process", "@(Get-ChildItem -LiteralPath $PSScriptRoot -File|Where-Object Extension -in '.ps1','.py','.cs','.exe'|ForEach-Object {@{path=$_.FullName;sha256=(Get-FileHash -LiteralPath $_.FullName).Hash}})|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $root 'source-hashes.json')\n$p=Start-Process")
p.write_text(s)
print('Diagnostic timing refined; collision identity/selection/removal unchanged.')
